pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address newDao, address sender, address target, bool emergency) public {
        vm.assume(newDao != address(0));
        vm.assume(newDao != address(this));
        vm.assume(sender != address(0));
        vm.assume(target != address(0));

        address daoBefore = c.DAO();

        vm.prank(address(this));
        c.setDAO(newDao);

        vm.prank(address(this));
        c.endConfiguration();

        vm.prank(address(this));
        try c.assertGovernanceApproved(sender, target, emergency) {} catch {}

        address daoAfter = c.DAO();

        assertTrue(daoBefore == daoAfter);
    }
}

