pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address sender, address target, bool emergency, address newDao) public {
        // sender must not be the DAO to trigger governance approval path
        vm.assume(sender != address(c) && sender != DAO());
        // newDao must differ from initial DAO
        vm.assume(newDao != DAO());

        // Setup: configure c to have a configured DAO and governer
        address initialDao = DAO();
        vm.prank(initialDao);
        c.configureFlashGovernance(address(0), 0, 0, false); // makes successfulProposal true for initialDao

        // Record DAO before assertGovernanceApproved
        address daoBefore = c.DAO();

        // Try to change DAO inside a call that triggers assertGovernanceApproved
        // We need a successful proposal call; use initialDao as sender again
        vm.startPrank(initialDao);
        c.setDAO(newDao); // change DAO before the call that hits governer

        bool ok = true;
        try c.assertGovernanceApproved(sender, target, emergency) {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();

        // After any non-reverting assertGovernanceApproved, DAO must equal what it was before
        if (ok) {
            assertEq(c.DAO(), daoBefore, "DAO must not change after non-reverting assertGovernanceApproved");
        } else {
            // If it reverted, we still check that DAO is either the original or that invariant holds
            // But the property is: if no revert, DAO unchanged
            assertTrue(true); // pass trivially when revert
        }
    }
}

