pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address sender, address target, bool emergency, address newDao) public {
        vm.assume(sender != address(0) && target != address(0));
        vm.assume(newDao != address(0) && newDao != address(c));
        vm.assume(sender != newDao);

        // Setup: make sender a successful proposal so they can call setDAO
        vm.prank(address(c));
        c.setDAO(newDao);
        vm.prank(newDao);
        c.setDAO(address(c));
        vm.prank(sender);
        c.setDAO(newDao);

        // Record the expected governer before calling assertGovernanceApproved
        address expectedGoverner = address(c.flashGoverner());

        try c.assertGovernanceApproved(sender, target, emergency) {
            // If the call does not revert, the cached governer must still equal the current DAO's flash governer
            address actualGoverner = address(c.flashGoverner());
            assertTrue(actualGoverner == expectedGoverner);
        } catch {
            // If it reverts, we don't assert anything about governer consistency
        }
    }
}

