// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address newDAO, address attacker, bool emergency) public {
        vm.assume(newDAO != address(0) && attacker != address(0) && attacker != newDAO && attacker != address(this));
        vm.assume(newDAO.code.length == 0 && attacker.code.length == 0);

        // attacker tries to change DAO
        vm.prank(attacker);
        c.setDAO(newDAO);

        // now call assertGovernanceApproved; the caller must be msg.sender of assertGovernanceApproved
        // we need governed[caller] == true to pass flashEnabled modifier
        // set up: make address(this) governed by calling setGoverned through ourselves (DAO=this)
        address[] memory govAddresses = new address[](1);
        govAddresses[0] = address(this);
        bool[] memory isGov = new bool[](1);
        isGov[0] = true;
        c.setGoverned(govAddresses, isGov);

        // now c.DAO() should be this (address(this)) if proper enforcement, else attacker's
        // call assertGovernanceApproved as governed address
        bool ok;
        try c.assertGovernanceApproved(address(0), address(0), emergency) {
            ok = true;
        } catch {
            ok = false;
        }

        // The property: if attacker changed DAO successfully, DAO should not be this anymore, but in correct contract it stays this.
        // Actually property: after setDAO by non-DAO/non-configured, DAO must remain address(this).
        // The assertion: DAO is still address(this) because only current DAO or before endConfiguration can change it.
        assertTrue(c.DAO() == address(this));
    }
}

